import java.util.*;

public class Main {
    static final int Z = 100;
    static final int N = Z * Z;
    static final int M = Z * Z * Z * 3;
    static final int INF = Integer.MAX_VALUE;

    static int[] px = new int[N], py = new int[N], head = new int[N], to = new int[M], ct = new int[M], w = new int[M], nt = new int[M];
    static int[] dist = new int[N], visited = new int[N], parent = new int[N], edge_id = new int[N];

    static int total_edges;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        total_edges = 0;
        Arrays.fill(head, -1);

        // add_edge method
        class Graph {
            void add_edge(int u, int v, int flow, int cost) {
                to[total_edges] = v;
                ct[total_edges] = cost;
                w[total_edges] = flow;
                nt[total_edges] = head[u];
                head[u] = total_edges++;
                to[total_edges] = u;
                ct[total_edges] = -cost;
                w[total_edges] = 0;
                nt[total_edges] = head[v];
                head[v] = total_edges++;
            }
        }
        Graph graph = new Graph();

        // spfa method
        boolean spfa(int s, int t) {
            Arrays.fill(dist, INF);
            Arrays.fill(visited, 0);
            Arrays.fill(parent, -1);
            Arrays.fill(edge_id, -1);
            dist[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                visited[u] = 0;
                for (int i = head[u]; i != -1; i = nt[i]) {
                    if (w[i] > 0 && dist[to[i]] > dist[u] + ct[i]) {
                        dist[to[i]] = dist[u] + ct[i];
                        parent[to[i]] = u;
                        edge_id[to[i]] = i;
                        if (visited[to[i]] == 0) {
                            visited[to[i]] = 1;
                            q.offer(to[i]);
                        }
                    }
                }
            }
            return dist[t] < INF;
        }

        // max_flow method
        int max_flow(int s, int t) {
            int total_flow = 0, total_cost = 0;
            while (spfa(s, t)) {
                int flow = INF;
                for (int i = t; i != s; i = parent[i]) {
                    flow = Math.min(flow, w[edge_id[i]]);
                }
                for (int i = t; i != s; i = parent[i]) {
                    w[edge_id[i]] -= flow;
                    w[edge_id[i] ^ 1] += flow;
                }
                total_cost += dist[t] * flow;
                total_flow += flow;
            }
            return total_cost;
        }

        int s = 0;
        int t = n * 100 + 1;

        // Initialize graph
        Arrays.fill(head, -1);
        total_edges = 0;

        // Add edges for sink
        for (int i = 1; i <= 100; ++i) {
            graph.add_edge(i, t, 100, 0);
        }

        // Read and add edges for initial positions
        for (int i = 1; i <= k; ++i) {
            int v = sc.nextInt();
            graph.add_edge(s, (v - 1) * 100 + 1, 1, 0);
        }

        // Add horizontal edges within each row
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j < 100; ++j) {
                int from_node = (i - 1) * 100 + j;
                int to_node = (i - 1) * 100 + j + 1;
                graph.add_edge(from_node, to_node, 100, c);
            }
        }

        // Read and add edges between nodes
        for (int i = 1; i <= m; ++i) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            for (int j = 1; j < 100; ++j) {
                int idx = (u - 1) * 100 + j;
                int idy = (v - 1) * 100 + j + 1;
                for (int k = 1; k <= 50; ++k) {
                    int cost_value = c + (k * k - (k - 1) * (k - 1)) * d;
                    graph.add_edge(idx, idy, 1, cost_value);
                }
            }
            for (int j = 1; j < 100; ++j) {
                int idx = (v - 1) * 100 + j;
                int idy = (u - 1) * 100 + j + 1;
                for (int k = 1; k <= 50; ++k) {
                    int cost_value = c + (k * k - (k - 1) * (k - 1)) * d;
                    graph.add_edge(idx, idy, 1, cost_value);
                }
            }
        }

        System.out.println(max_flow(s, t));
        sc.close();
    }
